import { LENSFLARE_MAX_FLARES } from '../../../../../src/extras/effects/lens-flare/passes/frame-pass-lens-flare.js';
import {
    LIGHTTYPE_DIRECTIONAL, LIGHTTYPE_OMNI, LIGHTTYPE_SPOT,
    PROJECTION_ORTHOGRAPHIC, PROJECTION_PERSPECTIVE
} from '../../../../../src/scene/constants.js';

const FAR = 100;

// the fraction of the far clip a directional source is placed at when the projection is
// orthographic, see the production implementation
const DIRECTIONAL_DEPTH = 0.98;

// linearised value of a 0.5 sRGB channel, as produced by Color#linear
const LINEAR_HALF = Math.pow(0.5, 2.2);

/**
 * Creates the camera component the passes of the effect expose to frameUpdate.
 *
 * @param {object} [options] - The options.
 * @param {boolean} [options.orthographic] - Whether the camera projection is orthographic.
 * @param {Vec3} [options.position] - The world position of the camera entity.
 * @param {boolean} [options.physicalUnits] - The scene physical units setting.
 * @param {Mat4} [options.projectionMatrix] - An explicit projection matrix, overriding the above.
 * @param {Mat4} [options.viewMatrix] - The world to view space matrix of the camera.
 * @returns {object} The camera component.
 */
function createCameraComponent(options = {}) {
    const {
        orthographic = false,
        position = new Vec3(0, 0, 0),
        physicalUnits = false,
        projectionMatrix = null,
        viewMatrix = new Mat4()
    } = options;

    const projection = projectionMatrix ?? (orthographic ?
        new Mat4().setOrtho(-10, 10, -10, 10, 0.1, FAR) :
        new Mat4().setPerspective(90, 1, 0.1, FAR));

    return {
        camera: {
            // the identity view matrix places the camera at the origin, looking down -Z
            viewMatrix,
            projectionMatrix: projection,
            farClip: FAR,
            projection: orthographic ? PROJECTION_ORTHOGRAPHIC : PROJECTION_PERSPECTIVE
        },
        entity: {
            getPosition: () => position
        },
        system: {
            app: {
                scene: { physicalUnits }
            }
        }
    };
}

/**
 * Creates the state frameUpdate reads from its instance, without building the passes of the
 * effect.
 *
 * @param {object} [cameraComponent] - The camera component, created when not supplied.
 * @returns {LensFlareEffect} The effect-like object.
 */
function createEffect(cameraComponent = createCameraComponent()) {
    const effect = Object.create(LensFlareEffect.prototype);
    effect.flares = [];
    effect._flareData = new Float32Array(LENSFLARE_MAX_FLARES * 8);
    effect._occlusionData = new Float32Array(LENSFLARE_MAX_FLARES * 8);
    effect._lastTime = 0;
    effect._pass = { cameraComponent };
    return effect;
}

/**
 * Runs frameUpdate of the effect for the given flares.
 *
 * @param {LensFlareEffect} effect - The effect.
 * @param {LensFlare[]} flares - The flares to process.
 * @returns {LensFlareEffect} The effect, for chaining.
 */
function update(effect, flares) {
    effect.flares = flares;
    LensFlareEffect.prototype.frameUpdate.call(effect, {});
    return effect;
}

/**
 * Reads the data written for one flare.
 *
 * @param {LensFlareEffect} effect - The effect.
 * @param {number} index - The index of the flare.
 * @returns {object} The flare and occlusion data of the flare.
 */
function dataAt(effect, index) {
    const base = index * 8;
    const flareData = effect._flareData;
    const occlusionData = effect._occlusionData;
    return {
        x: flareData[base + 0],
        y: flareData[base + 1],
        fade: flareData[base + 2],
        scale: flareData[base + 3],
        r: flareData[base + 4],
        g: flareData[base + 5],
        b: flareData[base + 6],
        depth: occlusionData[base + 2],
        occlusionRadius: occlusionData[base + 3],
        occlusionFade: occlusionData[base + 4],
        onScreen: occlusionData[base + 5]
    };
}

/**
 * Creates a light component stand-in.
 *
 * @param {object} [options] - The options.
 * @returns {object} The light component.
 */
function createLight(options = {}) {
    const {
        type = 'directional',
        lightType = LIGHTTYPE_DIRECTIONAL,
        enabled = true,
        entityEnabled = true,
        up = new Vec3(0, 0, -1),
        position = new Vec3(0, 0, 0),
        outerConeAngle = 30,
        innerConeAngle = 20,
        intensity = 1,
        luminance = 1,
        color = new Color(1, 1, 1)
    } = options;

    return {
        enabled,
        type,
        entity: {
            enabled: entityEnabled,
            up,
            getPosition: () => position
        },
        outerConeAngle,
        innerConeAngle,
        intensity,
        luminance,
        color,
        // the light resource of the component, read for the physical units conversion
        light: { type: lightType }
    };
}

