/**
 * Attaches a single layer of a texture to the currently bound framebuffer - a face of a cubemap,
 * a layer of a 2D array texture, a depth slice of a volume texture, or a 2D texture.
 *
 * @param {WebGL2RenderingContext} gl - The WebGL2 context.
 * @param {number} attachment - The attachment point.
 * @param {Texture} texture - The texture to attach.
 * @param {number} layer - The cubemap face, the array layer or the depth slice.
 * @param {number} mipLevel - The mip level.
 */
(gl, attachment, texture, layer, mipLevel) => {
    const glTexture = texture.impl._glTexture;
    if (texture.array || texture.volume) {
        gl.framebufferTextureLayer(gl.FRAMEBUFFER, attachment, glTexture, mipLevel, layer);
    } else {
        gl.framebufferTexture2D(gl.FRAMEBUFFER, attachment,
            texture._cubemap ? gl.TEXTURE_CUBE_MAP_POSITIVE_X + layer : gl.TEXTURE_2D,
            glTexture, mipLevel);
    }
}

_createMsaaMrtFramebuffers(device, target, colorBufferCount) {

        const gl = device.gl;
        this.colorMrtFramebuffers = [];

        for (let i = 0; i < colorBufferCount; ++i) {
            const colorBuffer = target.getColorBuffer(i);

            // src
            const srcFramebuffer = gl.createFramebuffer();
            device.setFramebuffer(srcFramebuffer);
            const buffer = this._glMsaaColorBuffers[i];

            gl.bindRenderbuffer(gl.RENDERBUFFER, buffer);
            gl.renderbufferStorageMultisample(gl.RENDERBUFFER, target._samples, colorBuffer.impl._glInternalFormat, target.width, target.height);
            gl.framebufferRenderbuffer(gl.FRAMEBUFFER, gl.COLOR_ATTACHMENT0, gl.RENDERBUFFER, buffer);

            gl.drawBuffers([gl.COLOR_ATTACHMENT0]);

            Debug.call(() => this._checkFbo(device, target, `MSAA-MRT-src${i}`));

            // dst
            const dstFramebuffer = gl.createFramebuffer();
            device.setFramebuffer(dstFramebuffer);
            attachTexture(gl, gl.COLOR_ATTACHMENT0, colorBuffer, target.layer, 0);

            this.colorMrtFramebuffers[i] = new FramebufferPair(srcFramebuffer, dstFramebuffer);

            Debug.call(() => this._checkFbo(device, target, `MSAA-MRT-dst${i}`));
        }
    }

