                data[w + 9] = quadY;
                data[w + 10] = quadZ;
                data[w + 11] = moveDirVec.y;
                data[w + 12] = id;
                data[w + 13] = moveDirVec.z;
                data[w + 14] = emitter.vbCPU[vbOffset + 3];
