                life: 1
            });
            const data = new Float32Array(15);

            // The emitterPos argument is ignored in world space; node.getPosition() is used instead.
            updater.update(data, [], particleTex, new Mat4(), [0, 0, 0], new Vec3(999, 999, 999), 1, false);

            expect(data[0]).toBeCloseTo(36, 4);
            expect(data[1]).toBeCloseTo(62, 4);
            expect(data[2]).toBeCloseTo(123, 4);
            expect(data[5]).toBeCloseTo(8, 4);
            expect(data[7]).toBeCloseTo(25, 4);
            expect(data[11]).toBeCloseTo(62, 4);
            expect(data[13]).toBeCloseTo(123, 4);
            expect(particleTex[0]).toBeCloseTo(36, 4);
            expect(particleTex[1]).toBeCloseTo(62, 4);
            expect(particleTex[2]).toBeCloseTo(123, 4);
        });

        it('divides local-space velocity by the node non-uniform scale', () => {
            const emitter = createEmitter({
                localSpace: true,
                meshInstance: {
                    node: createNode({
                        localScale: new Vec3(2, 4, 8)
                    })
                }
            });
            const updater = new ParticleCPUUpdater(emitter);
            const particleTex = createParticleTex(emitter);
            setParticle(emitter, particleTex, 0, {
                position: [0, 0, 0],
                rotation: 0.5,
                life: 1.75
            });
            const data = new Float32Array(15);

            updater.update(data, [], particleTex, new Mat4(), [0, 0, 0], new Vec3(), 0.25, false);

            expect(data[0]).toBeCloseTo(2.625, 4);
            expect(data[1]).toBeCloseTo(5.125, 4);
            expect(data[2]).toBeCloseTo(7.59375, 4);
            expect(data[5]).toBeCloseTo(16, 4);
        });

        it('wraps the rendered position without modifying the stored particle position', () => {
            const emitter = createEmitter({
                localSpace: false,
                wrap: true,
                wrapBounds: new Vec3(2, 4, 6),
                meshInstance: {
                    node: createNode({
                        position: new Vec3(10, 10, 10)
                    })
                }
            });
            disableMotion(emitter);
            const updater = new ParticleCPUUpdater(emitter);
            const particleTex = createParticleTex(emitter);
            setParticle(emitter, particleTex, 0, {
                position: [12.5, 9, 17],
                rotation: 0,
                life: 0.5
            });
            const data = new Float32Array(15);

            updater.update(data, [], particleTex, new Mat4(), [0, 0, 0], new Vec3(), 0, false);

            expect(data[0]).toBeCloseTo(9.5, 4);
            expect(data[1]).toBeCloseTo(11, 4);
            expect(data[2]).toBeCloseTo(8, 4);
            expect(particleTex[0]).toBeCloseTo(12.5, 4);
            expect(particleTex[1]).toBeCloseTo(9, 4);
            expect(particleTex[2]).toBeCloseTo(17, 4);
        });

        it('adds sphere-shaped initial velocity in a random direction', () => {
            const emitter = createEmitter({
                initialVelocity: 10,
                emitterShape: 1
            });
            disableMotion(emitter);
            emitter.qLocalVelocity = vectorChannel(1, 2, 3);
            emitter.qLocalVelocity2 = vectorChannel(1, 2, 3);
            const updater = new ParticleCPUUpdater(emitter);
            const particleTex = createParticleTex(emitter);
            setParticle(emitter, particleTex, 0, {
                life: 1,
                randomFactors: [0.5, 0.25, 0.75]
            });
            const data = new Float32Array(15);

            updater.update(data, [], particleTex, new Mat4(), [0, 0, 0], new Vec3(), 1, false);

            expect(data[7]).toBeCloseTo(1, 4);
            expect(data[11]).toBeCloseTo(-5.071068, 4);
            expect(data[13]).toBeCloseTo(10.071068, 4);
        });

        it('rejects box-shaped initial velocity because Vec3.FORWARD is immutable', () => {
            const emitter = createEmitter({
                initialVelocity: 5,
                emitterShape: 0
            });
            disableMotion(emitter);
            emitter.qLocalVelocity = vectorChannel(1, 2, 3);
            emitter.qLocalVelocity2 = vectorChannel(1, 2, 3);
            const updater = new ParticleCPUUpdater(emitter);
            const particleTex = createParticleTex(emitter);
            setParticle(emitter, particleTex, 0, { life: 1 });
            const data = new Float32Array(15);

            expect(() => {
                updater.update(data, [], particleTex, new Mat4(), [0, 0, 0], new Vec3(), 1, false);
            }).toThrow(TypeError);
        });

        it('respawns a particle that reached its lifetime and hides its quad', () => {
            const emitter = createEmitter({
                lifetime: 4,
                loop: false,
                rate: 1,
                rate2: 1
            });
            const updater = new ParticleCPUUpdater(emitter);
            const calcSpawnPosition = jest.spyOn(updater, 'calcSpawnPosition');
            const particleTex = createParticleTex(emitter);
            setParticle(emitter, particleTex, 0, {
                position: [3, 0, 4],
                life: 4,
                visible: 1
            });
            const data = new Float32Array(15);

            updater.update(data, [], particleTex, new Mat4(), [0, 0, 0], new Vec3(), 1, false);

            expect(calcSpawnPosition).toHaveBeenCalledWith(particleTex, expect.any(Mat4), [0, 0, 0], Vec3.ZERO, 0);
            expect(particleTex[3 + emitter.numParticlesPot * 4]).toBeCloseTo(1, 4);
            expect(particleTex[3 + emitter.numParticlesPot * 8]).toBe(-1);
            expect(data[8]).toBe(0);
            expect(data[9]).toBe(0);
            expect(data[10]).toBe(0);
            expect(data[12]).toBe(0);
        });

        it('keeps a looped particle visible after its life wraps below zero', () => {
            const emitter = createEmitter({
                lifetime: 4,
                loop: true,
                rate: 10,
                rate2: 10
            });
            const updater = new ParticleCPUUpdater(emitter);
            const particleTex = createParticleTex(emitter);
            setParticle(emitter, particleTex, 0, {
                position: [1, 2, 3],
                life: 4
            });
            const data = new Float32Array(15);

            updater.update(data, [], particleTex, new Mat4(), [0, 0, 0], new Vec3(), 1, false);

            expect(particleTex[3 + emitter.numParticlesPot * 4]).toBeCloseTo(-5, 4);
            expect(particleTex[3 + emitter.numParticlesPot * 8]).toBe(1);
            expect(data[8]).toBe(0);
            expect(data[9]).toBe(0);
            expect(data[10]).toBe(0);
        });

        it('marks a negative-life particle hidden when updating on stop', () => {
            const emitter = createEmitter({
                loop: false
            });
            const updater = new ParticleCPUUpdater(emitter);
            const calcSpawnPosition = jest.spyOn(updater, 'calcSpawnPosition');
            const particleTex = createParticleTex(emitter);
            setParticle(emitter, particleTex, 0, {
                position: [1, 2, 3],
                life: -1,
                visible: 1
            });
            const data = new Float32Array(15);

            updater.update(data, [], particleTex, new Mat4(), [0, 0, 0], new Vec3(), 0.25, true);

            expect(calcSpawnPosition).toHaveBeenCalled();
            expect(particleTex[3 + emitter.numParticlesPot * 4]).toBeCloseTo(-0.75, 4);
            expect(particleTex[3 + emitter.numParticlesPot * 8]).toBe(-1);
            expect(data[8]).toBe(0);
            expect(data[9]).toBe(0);
            expect(data[10]).toBe(0);
        });

        it.each([
            [1, new Vec3(2, 2, 3), -1],
            [2, new Vec3(), 0.5],
            [3, new Vec3(), -0.5]
        ])('stores the sort key for sort mode %i', (sortMode, cameraPosition, expectedKey) => {
            const emitter = createEmitter({
                sort: sortMode,
                camera: {
                    _node: {
                        getPosition: () => cameraPosition
                    }
                }
            });
            disableMotion(emitter);
            const updater = new ParticleCPUUpdater(emitter);
            const particleTex = createParticleTex(emitter);
            setParticle(emitter, particleTex, 0, {
                position: [1, 2, 3],
                life: 0.5
            });
            const vbToSort = [[0, 0]];
            const data = new Float32Array(15);

            updater.update(data, vbToSort, particleTex, new Mat4(), [0, 0, 0], new Vec3(), 0, false);

            expect(emitter.particleDistance[0]).toBeCloseTo(expectedKey, 4);
            expect(vbToSort[0][0]).toBe(0);
            expect(vbToSort[0][1]).toBeCloseTo(expectedKey, 4);
        });

        it('sorts the vertex buffer by particle distance and preserves the source in vbOld', () => {
            const emitter = createEmitter({
                numParticles: 3,
                sort: 2,
                camera: {
                    _node: {
                        getPosition: () => new Vec3()
                    }
                },
                vbCPU: new Float32Array([
                    10, 11, 12, 2,
                    20, 21, 22, 0,
                    30, 31, 32, 1
                ]),
                vbOld: new Float32Array(12),
                particleDistance: new Float32Array(3)
            });
            disableMotion(emitter);
            const updater = new ParticleCPUUpdater(emitter);
            const particleTex = createParticleTex(emitter);
            setParticle(emitter, particleTex, 0, { life: 0.1 });
            setParticle(emitter, particleTex, 1, { life: 0.3 });
            setParticle(emitter, particleTex, 2, { life: 0.2 });
            const vbToSort = [[0, 0], [0, 0], [0, 0]];
            const data = new Float32Array(3 * 15);

            updater.update(data, vbToSort, particleTex, new Mat4(), [0, 0, 0], new Vec3(), 0, false);

            expect(vbToSort[0][0]).toBe(1);
            expect(vbToSort[0][1]).toBeCloseTo(0.1, 5);
            expect(vbToSort[1][0]).toBe(0);
            expect(vbToSort[1][1]).toBeCloseTo(0.2, 5);
            expect(vbToSort[2][0]).toBe(2);
            expect(vbToSort[2][1]).toBeCloseTo(0.3, 5);
            expect(Array.from(emitter.vbOld)).toEqual([
                10, 11, 12, 2,
                20, 21, 22, 0,
                30, 31, 32, 1
            ]);
            expect(Array.from(emitter.vbCPU)).toEqual([
                20, 21, 22, 0,
                10, 11, 12, 2,
                30, 31, 32, 1
            ]);
        });

        it('does nothing when there are no particles', () => {
            const emitter = createEmitter({
                numParticles: 0,
                vbCPU: new Float32Array(0),
                vbOld: new Float32Array(0)
            });
            const updater = new ParticleCPUUpdater(emitter);
            const particleTex = createParticleTex(emitter);
            const data = new Float32Array([1, 2, 3]);

            updater.update(data, [], particleTex, new Mat4(), [0, 0, 0], new Vec3(), 1, false);

            expect(Array.from(data)).toEqual([1, 2, 3]);
        });
    });
});

