describe('ShadowRenderer#cullShadowCastersOmni', () => {
    it('clears every face list and emits the precull/postcull events around sorting', () => {
        const { subject, sorter, scene } = createSubject();
        const { light, renderData } = createLight();

        renderData[2].visibleCasters.push(createMeshInstance());
        renderData[5].visibleCasters.push(createMeshInstance());

        subject.cullShadowCastersOmni({}, light, []);

        expect(light.getRenderData).toHaveBeenCalledTimes(6);
        for (let face = 0; face < 6; face++) {
            expect(light.getRenderData).toHaveBeenNthCalledWith(face + 1, null, face);
            expect(renderData[face].visibleCasters).toEqual([]);
        }

        expect(sorter.sortMaterialMesh).toHaveBeenCalledTimes(6);
        for (let face = 0; face < 6; face++) {
            expect(sorter.sortMaterialMesh.mock.calls[face][0]).toBe(renderData[face].visibleCasters);
        }

        expect(scene.fire.mock.calls).toEqual([
            [EVENT_PRECULL, null],
            [EVENT_POSTCULL, null]
        ]);
        expect(scene.fire.mock.invocationCallOrder[0]).toBeLessThan(sorter.sortMaterialMesh.mock.invocationCallOrder[0]);
        expect(sorter.sortMaterialMesh.mock.invocationCallOrder[5]).toBeLessThan(scene.fire.mock.invocationCallOrder[1]);
    });

    it('classifies casters into the correct positive and negative axis faces', () => {
        const { subject, sorter } = createSubject();
        const { light, renderData } = createLight();
        const positiveX = createMeshInstance({ center: new Vec3(2, 0, 0) });
        const negativeX = createMeshInstance({ center: new Vec3(-2, 0, 0) });
        const positiveY = createMeshInstance({ center: new Vec3(0, 2, 0) });
        const negativeY = createMeshInstance({ center: new Vec3(0, -2, 0) });
        const positiveZ = createMeshInstance({ center: new Vec3(0, 0, 2) });
        const negativeZ = createMeshInstance({ center: new Vec3(0, 0, -2) });
        const casters = [positiveX, negativeX, positiveY, negativeY, positiveZ, negativeZ];

        subject.cullShadowCastersOmni({}, light, casters);

        expect(renderData[0].visibleCasters).toEqual([positiveX]);
        expect(renderData[1].visibleCasters).toEqual([negativeX]);
        expect(renderData[2].visibleCasters).toEqual([positiveY]);
        expect(renderData[3].visibleCasters).toEqual([negativeY]);
        expect(renderData[4].visibleCasters).toEqual([positiveZ]);
        expect(renderData[5].visibleCasters).toEqual([negativeZ]);

        casters.forEach((caster) => {
            expect(caster.visibleThisFrame).toBe(true);
        });

        expect(sorter.sortMaterialMesh).toHaveBeenCalledTimes(6);
    });

    it('adds a caster to every face whose frustum it overlaps', () => {
        const { subject } = createSubject();
        const { light, renderData } = createLight();
        const allFaces = createMeshInstance({
            center: new Vec3(0, 0, 0),
            halfExtents: new Vec3(1, 1, 1)
        });
        const positiveCorner = createMeshInstance({ center: new Vec3(2, 2, 2) });
        const negativeCorner = createMeshInstance({ center: new Vec3(-2, -2, -2) });

        subject.cullShadowCastersOmni({}, light, [allFaces, positiveCorner, negativeCorner]);

        for (let face = 0; face < 6; face++) {
            expect(renderData[face].visibleCasters).toContain(allFaces);
        }

        expect(renderData[0].visibleCasters).toEqual([allFaces, positiveCorner]);
        expect(renderData[1].visibleCasters).toEqual([allFaces, negativeCorner]);
        expect(renderData[2].visibleCasters).toEqual([allFaces, positiveCorner]);
        expect(renderData[3].visibleCasters).toEqual([allFaces, negativeCorner]);
        expect(renderData[4].visibleCasters).toEqual([allFaces, positiveCorner]);
        expect(renderData[5].visibleCasters).toEqual([allFaces, negativeCorner]);
    });

    it('uses the light position as the origin of the caster classification', () => {
        const { subject } = createSubject();
        const lightPosition = new Vec3(100, -20, 7);
        const { light, renderData } = createLight(lightPosition);
        const casterAtLight = createMeshInstance({
            center: lightPosition.clone(),
            halfExtents: new Vec3(1, 1, 1)
        });
        const casterFarFromLight = createMeshInstance({
            center: new Vec3(102, -20, 7)
        });

        subject.cullShadowCastersOmni({}, light, [casterAtLight, casterFarFromLight]);

        for (let face = 0; face < 6; face++) {
            expect(renderData[face].visibleCasters).toContain(casterAtLight);
        }
        expect(renderData[0].visibleCasters).toContain(casterFarFromLight);
        expect(renderData[1].visibleCasters).not.toContain(casterFarFromLight);
        expect(casterAtLight.visibleThisFrame).toBe(true);
        expect(casterFarFromLight.visibleThisFrame).toBe(true);
    });

    it('rejects casters inside the near planes, beyond the far planes, or outside the bounds', () => {
        const { subject } = createSubject();
        const { light, renderData } = createLight();
        const atLightOrigin = createMeshInstance({
            center: new Vec3(0, 0, 0),
            halfExtents: new Vec3(0, 0, 0)
        });
        const exactlyAtFarPlane = createMeshInstance({
            center: new Vec3(10.5, 0, 0),
            halfExtents: new Vec3(0.5, 0.5, 0.5)
        });
        const outsideBounds = createMeshInstance({
            center: new Vec3(10.6, 10.6, 10.6),
            halfExtents: new Vec3(0.1, 0.1, 0.1)
        });
        const justInsideFarPlane = createMeshInstance({
            center: new Vec3(9.5, 0, 0),
            halfExtents: new Vec3(0.5, 0.5, 0.5)
        });

        subject.cullShadowCastersOmni({}, light, [atLightOrigin, exactlyAtFarPlane, outsideBounds, justInsideFarPlane]);

        for (let face = 0; face < 6; face++) {
            expect(renderData[face].visibleCasters).not.toContain(atLightOrigin);
            expect(renderData[face].visibleCasters).not.toContain(exactlyAtFarPlane);
            expect(renderData[face].visibleCasters).not.toContain(outsideBounds);
        }
        expect(renderData[0].visibleCasters).toEqual([justInsideFarPlane]);
        expect(atLightOrigin.visibleThisFrame).toBe(false);
        expect(exactlyAtFarPlane.visibleThisFrame).toBe(false);
        expect(outsideBounds.visibleThisFrame).toBe(false);
        expect(justInsideFarPlane.visibleThisFrame).toBe(true);
    });

    it('skips casters which do not cast shadows or are not visible', () => {
        const { subject } = createSubject();
        const { light, renderData } = createLight();
        const noShadow = createMeshInstance({
            center: new Vec3(1, 0, 0),
            castShadow: false
        });
        const invisible = createMeshInstance({
            center: new Vec3(2, 0, 0),
            visible: false
        });

        subject.cullShadowCastersOmni({}, light, [noShadow, invisible]);

        for (let face = 0; face < 6; face++) {
            expect(renderData[face].visibleCasters).toEqual([]);
        }
        expect(noShadow.visibleThisFrame).toBe(false);
        expect(invisible.visibleThisFrame).toBe(false);
        expect(noShadow.aabbGetter).not.toHaveBeenCalled();
        expect(invisible.aabbGetter).not.toHaveBeenCalled();
    });

    it('adds a culling-disabled caster to all faces without testing its bounds', () => {
        const { subject } = createSubject();
        const { light, renderData } = createLight();
        const noCull = createMeshInstance({
            center: new Vec3(1000, -1000, 1000),
            halfExtents: new Vec3(100, 100, 100),
            cull: false
        });

        subject.cullShadowCastersOmni({}, light, [noCull]);

        for (let face = 0; face < 6; face++) {
            expect(renderData[face].visibleCasters).toEqual([noCull]);
        }
        expect(noCull.visibleThisFrame).toBe(true);
        expect(noCull.aabbGetter).not.toHaveBeenCalled();
        expect(noCull._isVisible).not.toHaveBeenCalled();
    });

    it('evaluates custom visibility once per face and only adds the caster to visible faces', () => {
        const { subject } = createSubject();
        const { light, renderData } = createLight();
        const visibleFaces = new Set([1, 4]);
        const customCulled = createMeshInstance({
            center: new Vec3(500, 500, 500),
            isVisibleFunc: () => true,
            isVisible: camera => visibleFaces.has(renderData.findIndex(data => data.shadowCamera === camera))
        });
        const neverVisible = createMeshInstance({
            isVisibleFunc: () => false,
            isVisible: () => false
        });

        subject.cullShadowCastersOmni({}, light, [customCulled, neverVisible]);

        expect(customCulled._isVisible).toHaveBeenCalledTimes(6);
        expect(neverVisible._isVisible).toHaveBeenCalledTimes(6);
        for (let face = 0; face < 6; face++) {
            expect(customCulled._isVisible).toHaveBeenNthCalledWith(face + 1, renderData[face].shadowCamera);
        }
        expect(renderData[0].visibleCasters).toEqual([]);
        expect(renderData[1].visibleCasters).toEqual([customCulled]);
        expect(renderData[2].visibleCasters).toEqual([]);
        expect(renderData[3].visibleCasters).toEqual([]);
        expect(renderData[4].visibleCasters).toEqual([customCulled]);
        expect(renderData[5].visibleCasters).toEqual([]);
        expect(customCulled.visibleThisFrame).toBe(true);
        expect(neverVisible.visibleThisFrame).toBe(false);
        expect(customCulled.aabbGetter).not.toHaveBeenCalled();
        expect(neverVisible.aabbGetter).not.toHaveBeenCalled();
    });

    it('collects casters from each unique layer containing the light when no caster array is supplied', () => {
        const { subject } = createSubject();
        const { light, renderData } = createLight();
        const first = createMeshInstance({ cull: false });
        const second = createMeshInstance({ cull: false });
        const ignored = createMeshInstance({ cull: false });
        const firstLayer = {
            _lightsSet: new Set([light]),
            shadowCasters: [first]
        };
        const secondLayer = {
            _lightsSet: new Set([light]),
            shadowCasters: [second]
        };
        const unrelatedLayer = {
            _lightsSet: new Set(),
            shadowCasters: [ignored]
        };
        const comp = {
            layerList: [firstLayer, secondLayer, firstLayer, unrelatedLayer]
        };

        subject.cullShadowCastersOmni(comp, light);

        for (let face = 0; face < 6; face++) {
            expect(renderData[face].visibleCasters).toEqual([first, second]);
        }
        expect(first.visibleThisFrame).toBe(true);
        expect(second.visibleThisFrame).toBe(true);
        expect(ignored.visibleThisFrame).toBe(false);
    });

    it('works without a scene while still sorting every face list', () => {
        const { subject, sorter } = createSubject({ withScene: false });
        const { light } = createLight();
        const caster = createMeshInstance({ cull: false });

        expect(() => subject.cullShadowCastersOmni({}, light, [caster])).not.toThrow();
        expect(sorter.sortMaterialMesh).toHaveBeenCalledTimes(6);
    });

    it('reports an assertion when given a non-omni light', () => {
        const consoleError = jest.spyOn(console, 'error').mockImplementation(() => {});
        try {
            const { subject } = createSubject();
            const { light } = createLight();
            light._type = LIGHTTYPE_DIRECTIONAL;

            subject.cullShadowCastersOmni({}, light, []);

            expect(consoleError).toHaveBeenCalledWith('ASSERT FAILED: ');
        } finally {
            consoleError.mockRestore();
        }
    });
});

