    SEMANTIC_TEXCOORD1,
    SEMANTIC_TEXCOORD2,
    SEMANTIC_TEXCOORD3,
    SEMANTIC_TEXCOORD4,
    SEMANTIC_TEXCOORD5,
    SEMANTIC_TEXCOORD6,
    SEMANTIC_TEXCOORD7
} from '../../../../../src/platform/graphics/constants.js';
import {
    SHADER_PREPASS,
    SPRITE_RENDERMODE_SIMPLE,
    SPRITE_RENDERMODE_SLICED,
    SPRITE_RENDERMODE_TILED
} from '../../../../../src/scene/constants.js';

const createDevice = (isWebGPU = false) => ({
    isWebGPU,
    hasTranspilers: true,
    on() {}
});

const createShader = ({ options = {}, allowWGSL = true, device = createDevice() } = {}) => {
    const shaderOptions = Object.assign(new LitShaderOptions(), {
        // keep the default setup deterministic: no lighting-driven normals
        clusteredLightingEnabled: false
    }, options);
    return new LitShader(device, shaderOptions, allowWGSL);
};

const generate = (shader, useUv = [], useUnmodifiedUv = [], mapTransforms = []) => {
    shader.generateVertexShader(useUv, useUnmodifiedUv, mapTransforms);
    return shader;
};

const getVaryingNames = (shader) => {
    return [...shader.varyingsCode.matchAll(/^#define VARYING_(\w+)$/gm)].map(match => match[1]);
};

const expectDefine = (map, name, value) => {
    expect(map.has(name)).toBe(true);
    expect(map.get(name)).toEqual(value);
};

const expectNoDefine = (map, name) => {
    expect(map.has(name)).toBe(false);
};

describe('LitShader#generateVertexShader', () => {

    describe('baseline output', () => {

        it('always emits the position varying and the litMainVS vertex shader', () => {
            const shader = generate(createShader());

            expect(shader.varyingsCode).toBe('#define VARYING_VPOSITIONW\nvarying vec3 vPositionW;\n');
            expect(getVaryingNames(shader)).toEqual(['VPOSITIONW']);
            expect(shader.includes.get('varyingsVS')).toBe(shader.varyingsCode);
            expect(shader.includes.get('varyingsPS')).toBe(shader.varyingsCode);
            expect(shader.vshader).toBe('\n            #include "litMainVS"\n        ');
        });

        it('starts with the constructor attributes and zero uv/transform counts', () => {
            const shader = generate(createShader());

            expect(shader.attributes).toEqual({ vertex_position: SEMANTIC_POSITION });
            expect([...shader.vDefines]).toEqual([
                ['UV_SET_COUNT', 0],
                ['UV_VARYING_SET_COUNT', 0],
                ['UV_TRANSFORMS_COUNT', 0]
            ]);
            expect([...shader.fDefines]).toEqual([]);
        });

        it('appends generated varyings to existing varyings code', () => {
            const shader = createShader();
            shader.varyingsCode = 'existing code\n';
            generate(shader);

            expect(shader.varyingsCode).toBe('existing code\n#define VARYING_VPOSITIONW\nvarying vec3 vPositionW;\n');
            expect(shader.includes.get('varyingsVS')).toBe(shader.varyingsCode);
        });

        it('keeps existing unrelated defines and attributes', () => {
            const shader = createShader();
            shader.vDefines.set('SOME_EXISTING_DEFINE', 5);
            shader.attributes.vertex_texCoord1 = SEMANTIC_TEXCOORD1;

            generate(shader);

            expectDefine(shader.vDefines, 'SOME_EXISTING_DEFINE', 5);
            expect(shader.attributes.vertex_texCoord1).toBe(SEMANTIC_TEXCOORD1);
            expect(shader.attributes.vertex_position).toBe(SEMANTIC_POSITION);
        });
    });

    describe('nine-sliced mode', () => {

        it.each([SPRITE_RENDERMODE_SLICED, SPRITE_RENDERMODE_TILED])('sets NINESLICED for render mode %i', (mode) => {
            const shader = generate(createShader({ options: { nineSlicedMode: mode } }));

            expectDefine(shader.vDefines, 'NINESLICED', true);
            expectNoDefine(shader.fDefines, 'NINESLICED');
        });

        it.each([SPRITE_RENDERMODE_SIMPLE, 99])('does not set NINESLICED for render mode %i', (mode) => {
            const shader = generate(createShader({ options: { nineSlicedMode: mode } }));

            expectNoDefine(shader.vDefines, 'NINESLICED');
        });
    });

    describe('linear depth', () => {

        it('adds the linear depth define and float varying', () => {
            const shader = generate(createShader({ options: { linearDepth: true } }));

            expectDefine(shader.vDefines, 'LINEAR_DEPTH', true);
            expect(getVaryingNames(shader)).toEqual(['VPOSITIONW', 'VLINEARDEPTH']);
            expect(shader.varyingsCode).toContain('varying float vLinearDepth;\n');
            expectNoDefine(shader.fDefines, 'LINEAR_DEPTH');
        });

        it('does not add linear depth output when disabled', () => {
            const shader = generate(createShader({ options: { linearDepth: false } }));

            expectNoDefine(shader.vDefines, 'LINEAR_DEPTH');
            expect(getVaryingNames(shader)).toEqual(['VPOSITIONW']);
        });
    });

    describe('dynamic refraction', () => {

        it('adds the dynamic refraction define and model scale varying for a forward pass', () => {
            const shader = generate(createShader({
                options: { useRefraction: true, useDynamicRefraction: true }
            }));

            expect(shader.shaderPassInfo.isForward).toBe(true);
            expectDefine(shader.vDefines, 'LIT_DYNAMIC_REFRACTION', true);
            expect(getVaryingNames(shader)).toContain('VMODELSCALE');
            expect(shader.varyingsCode).toContain('varying vec3 vModelScale;\n');
        });

        it('does not add dynamic refraction for a non-forward pass', () => {
            const shader = generate(createShader({
                options: { useRefraction: true, useDynamicRefraction: true, pass: SHADER_PREPASS }
            }));

            expect(shader.shaderPassInfo.isForward).toBeUndefined();
            expectNoDefine(shader.vDefines, 'LIT_DYNAMIC_REFRACTION');
            expect(getVaryingNames(shader)).not.toContain('VMODELSCALE');
        });

        it.each([
            ['useRefraction disabled', { useRefraction: false, useDynamicRefraction: true }],
            ['useDynamicRefraction disabled', { useRefraction: true, useDynamicRefraction: false }]
        ])('does not add dynamic refraction when %s', (_, options) => {
            const shader = generate(createShader({ options }));

            expectNoDefine(shader.vDefines, 'LIT_DYNAMIC_REFRACTION');
            expect(getVaryingNames(shader)).not.toContain('VMODELSCALE');
        });
    });

    describe('normals and tangents', () => {

        it('adds normal output when normals are needed', () => {
            const shader = createShader();
            shader.needsNormal = true;
            generate(shader);

            expectDefine(shader.vDefines, 'NORMALS', true);
            expect(shader.attributes.vertex_normal).toBe(SEMANTIC_NORMAL);
            expect(getVaryingNames(shader)).toEqual(['VPOSITIONW', 'VNORMALW']);
            expect(shader.varyingsCode).toContain('varying vec3 vNormalW;\n');
        });

        it('does not add normal output when normals are not needed', () => {
            const shader = createShader({ options: { hasTangents: true, useHeights: true } });
            shader.needsNormal = false;
            generate(shader);

            expectNoDefine(shader.vDefines, 'NORMALS');
            expect(shader.attributes).not.toHaveProperty('vertex_normal');
            expect(getVaryingNames(shader)).toEqual(['VPOSITIONW']);
        });

        it.each([
            ['useHeights', { useHeights: true }],
            ['useNormals', { useNormals: true }],
            ['useClearCoatNormals', { useClearCoatNormals: true }],
            ['enableGGXSpecular', { enableGGXSpecular: true }]
        ])('emits tangent and binormal varyings for hasTangents with %s', (_, options) => {
            const shader = createShader({ options: { hasTangents: true, ...options } });
            shader.needsNormal = true;
            generate(shader);

            expectDefine(shader.vDefines, 'TANGENTS', true);
            expect(shader.attributes.vertex_tangent).toBe(SEMANTIC_TANGENT);
            expect(getVaryingNames(shader)).toEqual(['VPOSITIONW', 'VNORMALW', 'VTANGENTW', 'VBINORMALW']);
            expect(shader.varyingsCode).toContain('varying vec3 vTangentW;\n');
            expect(shader.varyingsCode).toContain('varying vec3 vBinormalW;\n');
            expectNoDefine(shader.vDefines, 'GGX_SPECULAR');
        });

        it('does not emit tangent output for hasTangents without a tangent-consuming option', () => {
            const shader = createShader({ options: { hasTangents: true } });
            shader.needsNormal = true;
            generate(shader);

            expectNoDefine(shader.vDefines, 'TANGENTS');
            expectNoDefine(shader.vDefines, 'GGX_SPECULAR');
            expect(shader.attributes).not.toHaveProperty('vertex_tangent');
            expect(getVaryingNames(shader)).toEqual(['VPOSITIONW', 'VNORMALW']);
        });

        it('uses the object space up varying for GGX specular when there are no tangents', () => {
            const shader = createShader({ options: { hasTangents: false, enableGGXSpecular: true } });
            shader.needsNormal = true;
            generate(shader);

            expectDefine(shader.vDefines, 'GGX_SPECULAR', true);
            expectNoDefine(shader.vDefines, 'TANGENTS');
            expect(shader.attributes).not.toHaveProperty('vertex_tangent');
            expect(getVaryingNames(shader)).toEqual(['VPOSITIONW', 'VNORMALW', 'VOBJECTSPACEUPW']);
            expect(shader.varyingsCode).toContain('varying vec3 vObjectSpaceUpW;\n');
        });

        it('prefers tangents over GGX object space up when both are available', () => {
            const shader = createShader({ options: { hasTangents: true, enableGGXSpecular: true } });
            shader.needsNormal = true;
            generate(shader);

            expectDefine(shader.vDefines, 'TANGENTS', true);
            expectNoDefine(shader.vDefines, 'GGX_SPECULAR');
            expect(getVaryingNames(shader)).toEqual(['VPOSITIONW', 'VNORMALW', 'VTANGENTW', 'VBINORMALW']);
        });
    });

    describe('uv sets', () => {

        it('adds defines and attributes for used uv sets and expands extra sets', () => {
            const shader = generate(createShader(), [true, false, true]);

            expectDefine(shader.vDefines, 'UV0', true);
            expectNoDefine(shader.vDefines, 'UV1');
            expectDefine(shader.vDefines, 'UV2', true);
            expectDefine(shader.vDefines, '{UV_SET_0}', 2);
            expectDefine(shader.vDefines, 'UV_SET_COUNT', 1);
            expectDefine(shader.vDefines, 'UV_VARYING_SET_COUNT', 0);
            expect(shader.attributes.vertex_texCoord0).toBe(SEMANTIC_TEXCOORD0);
            expect(shader.attributes).not.toHaveProperty('vertex_texCoord1');
            expect(shader.attributes.vertex_texCoord2).toBe(SEMANTIC_TEXCOORD2);
        });

        it('handles all eight uv sets and counts only the additional sets', () => {
            const shader = generate(createShader(), new Array(8).fill(true));
            const uvSemantics = [
                SEMANTIC_TEXCOORD0, SEMANTIC_TEXCOORD1, SEMANTIC_TEXCOORD2, SEMANTIC_TEXCOORD3,
                SEMANTIC_TEXCOORD4, SEMANTIC_TEXCOORD5, SEMANTIC_TEXCOORD6, SEMANTIC_TEXCOORD7
            ];

            for (let i = 0; i < 8; i++) {
                expectDefine(shader.vDefines, `UV${i}`, true);
                expect(shader.attributes[`vertex_texCoord${i}`]).toBe(uvSemantics[i]);
            }
            expectDefine(shader.vDefines, 'UV_SET_COUNT', 6);
            expectDefine(shader.vDefines, '{UV_SET_0}', 2);
            expectDefine(shader.vDefines, '{UV_SET_5}', 7);
            expectNoDefine(shader.vDefines, '{UV_SET_6}');
        });

        it('adds unmodified uv defines and varyings, expanding extra uv varying sets', () => {
            const shader = generate(createShader(), [false, false, false], [false, true, true]);

            expectNoDefine(shader.vDefines, 'UV0_UNMODIFIED');
            expectDefine(shader.vDefines, 'UV1_UNMODIFIED', true);
            expectDefine(shader.vDefines, 'UV2_UNMODIFIED', true);
            expectDefine(shader.vDefines, '{UV_VARYING_SET_0}', 2);
            expectDefine(shader.vDefines, 'UV_VARYING_SET_COUNT', 1);
            expect(getVaryingNames(shader)).toEqual(['VPOSITIONW', 'VUV1', 'VUV2']);
            expect(shader.varyingsCode).toContain('varying vec2 vUv1;\n');
            expect(shader.varyingsCode).toContain('varying vec2 vUv2;\n');
        });

        it('does not add unmodified uv output when no flag is set', () => {
            const shader = generate(createShader(), [true, true], [false, false]);

            expectDefine(shader.vDefines, 'UV_VARYING_SET_COUNT', 0);
            expect(getVaryingNames(shader)).toEqual(['VPOSITIONW']);
        });

        it('uses the useUv array length to drive the combined uv loop', () => {
            const shader = generate(createShader(), [true], [true, true]);

            expectDefine(shader.vDefines, 'UV0_UNMODIFIED', true);
            expectNoDefine(shader.vDefines, 'UV1_UNMODIFIED');
            expectDefine(shader.vDefines, 'UV_VARYING_SET_COUNT', 0);
            expect(getVaryingNames(shader)).toEqual(['VPOSITIONW', 'VUV0']);
        });

        it('ignores unmodified uv entries beyond the useUv length', () => {
            const shader = generate(createShader(), [], [true]);

            expectNoDefine(shader.vDefines, 'UV0_UNMODIFIED');
            expectDefine(shader.vDefines, 'UV_VARYING_SET_COUNT', 0);
            expect(getVaryingNames(shader)).toEqual(['VPOSITIONW']);
        });
    });

    describe('texture transforms', () => {

        it('registers a varying and transform defines for a single transform', () => {
            const shader = generate(createShader(), [], [], [
                { id: 5, uv: 2, name: 'diffuse' }
            ]);

            expectDefine(shader.vDefines, '{TRANSFORM_NAME_0}', 'texture_diffuseMapTransform');
            expectDefine(shader.vDefines, '{TRANSFORM_UV_0}', 2);
            expectDefine(shader.vDefines, '{TRANSFORM_ID_0}', 5);
            expectDefine(shader.vDefines, 'UV_TRANSFORMS_COUNT', 1);
            expect(getVaryingNames(shader)).toEqual(['VPOSITIONW', 'VUV2_5']);
            expect(shader.varyingsCode).toContain('varying vec2 vUV2_5;\n');
        });

        it('registers multiple unique transform ids and uv sets sequentially', () => {
            const shader = generate(createShader(), [], [], [
                { id: 3, uv: 0, name: 'diffuse' },
                { id: 3, uv: 1, name: 'diffuse' },
                { id: 4, uv: 0, name: 'normal' }
            ]);

            expectDefine(shader.vDefines, 'UV_TRANSFORMS_COUNT', 3);
            expectDefine(shader.vDefines, '{TRANSFORM_NAME_0}', 'texture_diffuseMapTransform');
            expectDefine(shader.vDefines, '{TRANSFORM_UV_0}', 0);
            expectDefine(shader.vDefines, '{TRANSFORM_ID_0}', 3);
            expectDefine(shader.vDefines, '{TRANSFORM_NAME_1}', 'texture_diffuseMapTransform');
            expectDefine(shader.vDefines, '{TRANSFORM_UV_1}', 1);
            expectDefine(shader.vDefines, '{TRANSFORM_ID_1}', 3);
            expectDefine(shader.vDefines, '{TRANSFORM_NAME_2}', 'texture_normalMapTransform');
            expectDefine(shader.vDefines, '{TRANSFORM_UV_2}', 0);
            expectDefine(shader.vDefines, '{TRANSFORM_ID_2}', 4);
            expect(getVaryingNames(shader)).toEqual(['VPOSITIONW', 'VUV0_3', 'VUV1_3', 'VUV0_4']);
        });

        it('deduplicates transforms for the same id and uv set', () => {
            const shader = generate(createShader(), [], [], [
                { id: 7, uv: 2, name: 'first' },
                { id: 7, uv: 2, name: 'second' }
            ]);

            expectDefine(shader.vDefines, 'UV_TRANSFORMS_COUNT', 1);
            expectDefine(shader.vDefines, '{TRANSFORM_NAME_0}', 'texture_firstMapTransform');
            expectNoDefine(shader.vDefines, '{TRANSFORM_NAME_1}');
            expect(getVaryingNames(shader)).toEqual(['VPOSITIONW', 'VUV2_7']);
        });

        it('adds no transform output when there are no transforms', () => {
            const shader = generate(createShader(), [], [], []);

            expectDefine(shader.vDefines, 'UV_TRANSFORMS_COUNT', 0);
            expectNoDefine(shader.vDefines, '{TRANSFORM_NAME_0}');
            expect(getVaryingNames(shader)).toEqual(['VPOSITIONW']);
        });
    });

    describe('vertex colors', () => {

        it('adds the color attribute, define and varying', () => {
            const shader = generate(createShader({ options: { vertexColors: true } }));

            expectDefine(shader.vDefines, 'VERTEX_COLOR', true);
            expect(shader.attributes.vertex_color).toBe(SEMANTIC_COLOR);
            expect(getVaryingNames(shader)).toEqual(['VPOSITIONW', 'VVERTEXCOLOR']);
            expect(shader.varyingsCode).toContain('varying vec4 vVertexColor;\n');
        });

        it('adds the gamma define with an empty value when enabled with vertex colors', () => {
            const shader = generate(createShader({
                options: { vertexColors: true, useVertexColorGamma: true }
            }));

            expectDefine(shader.vDefines, 'STD_VERTEX_COLOR_GAMMA', '');
        });

        it('ignores vertex color gamma when vertex colors are disabled', () => {
            const shader = generate(createShader({
                options: { vertexColors: false, useVertexColorGamma: true }
            }));

            expectNoDefine(shader.vDefines, 'VERTEX_COLOR');
            expectNoDefine(shader.vDefines, 'STD_VERTEX_COLOR_GAMMA');
            expect(shader.attributes).not.toHaveProperty('vertex_color');
            expect(getVaryingNames(shader)).toEqual(['VPOSITIONW']);
        });
    });

    describe('msdf text', () => {

        it('adds msdf attributes and define when both flags are set', () => {
            const shader = generate(createShader({
                options: { useMsdf: true, msdfTextAttribute: true }
            }));

            expectDefine(shader.vDefines, 'MSDF', true);
            expect(shader.attributes.vertex_outlineParameters).toBe(SEMANTIC_ATTR8);
            expect(shader.attributes.vertex_shadowParameters).toBe(SEMANTIC_ATTR9);
        });

        it.each([
            ['useMsdf disabled', { useMsdf: false, msdfTextAttribute: true }],
            ['msdfTextAttribute disabled', { useMsdf: true, msdfTextAttribute: false }]
        ])('adds no msdf output when %s', (_, options) => {
            const shader = generate(createShader({ options }));

            expectNoDefine(shader.vDefines, 'MSDF');
            expect(shader.attributes).not.toHaveProperty('vertex_outlineParameters');
            expect(shader.attributes).not.toHaveProperty('vertex_shadowParameters');
        });
    });

    describe('morphing', () => {

        it('adds shared morphing position defines and the vertex id attribute', () => {
            const shader = generate(createShader({ options: { useMorphPosition: true } }));

            expectDefine(shader.vDefines, 'MORPHING', true);
            expectDefine(shader.vDefines, 'MORPHING_POSITION', true);
            expectNoDefine(shader.vDefines, 'MORPHING_NORMAL');
            expectNoDefine(shader.vDefines, 'MORPHING_INT');
            expectDefine(shader.fDefines, 'MORPHING', true);
            expectDefine(shader.fDefines, 'MORPHING_POSITION', true);
            expectNoDefine(shader.fDefines, 'MORPHING_NORMAL');
            expect(shader.attributes.morph_vertex_id).toBe(SEMANTIC_ATTR15);
        });

        it('adds morphing normal defines when only normals morph', () => {
            const shader = generate(createShader({ options: { useMorphNormal: true } }));

            expectDefine(shader.vDefines, 'MORPHING', true);
            expectDefine(shader.vDefines, 'MORPHING_NORMAL', true);
            expectNoDefine(shader.vDefines, 'MORPHING_POSITION');
            expectDefine(shader.fDefines, 'MORPHING', true);
            expectDefine(shader.fDefines, 'MORPHING_NORMAL', true);
            expect(shader.attributes.morph_vertex_id).toBe(SEMANTIC_ATTR15);
        });

        it('adds all morphing defines, including texture based interpolation, in both stages', () => {
            const shader = generate(createShader({
                options: {
                    useMorphPosition: true,
                    useMorphNormal: true,
                    useMorphTextureBasedInt: true
                }
            }));

            for (const map of [shader.vDefines, shader.fDefines]) {
                expectDefine(map, 'MORPHING', true);
                expectDefine(map, 'MORPHING_INT', true);
                expectDefine(map, 'MORPHING_POSITION', true);
                expectDefine(map, 'MORPHING_NORMAL', true);
            }
            expect(shader.attributes.morph_vertex_id).toBe(SEMANTIC_ATTR15);
        });

        it('ignores texture based morphing when no position or normal morphing is enabled', () => {
            const shader = generate(createShader({ options: { useMorphTextureBasedInt: true } }));

            for (const map of [shader.vDefines, shader.fDefines]) {
                expectNoDefine(map, 'MORPHING');
                expectNoDefine(map, 'MORPHING_INT');
                expectNoDefine(map, 'MORPHING_POSITION');
                expectNoDefine(map, 'MORPHING_NORMAL');
            }
            expect(shader.attributes).not.toHaveProperty('morph_vertex_id');
        });
    });

    describe('skinning', () => {

        it('adds skinning attributes and the shared SKIN define', () => {
            const shader = generate(createShader({ options: { skin: true, batch: false } }));

            expect(shader.attributes.vertex_boneIndices).toBe(SEMANTIC_BLENDINDICES);
            expect(shader.attributes.vertex_boneWeights).toBe(SEMANTIC_BLENDWEIGHT);
            expectDefine(shader.vDefines, 'SKIN', true);
            expectDefine(shader.fDefines, 'SKIN', true);
            expectNoDefine(shader.vDefines, 'BATCH');
            expectNoDefine(shader.fDefines, 'BATCH');
        });

        it('uses batching instead of skinning when batch is enabled', () => {
            const shader = generate(createShader({ options: { skin: true, batch: true } }));

            expect(shader.attributes.vertex_boneIndices).toBe(SEMANTIC_BLENDINDICES);
            expect(shader.attributes).not.toHaveProperty('vertex_boneWeights');
            expectDefine(shader.vDefines, 'BATCH', true);
            expectDefine(shader.fDefines, 'BATCH', true);
            expectNoDefine(shader.vDefines, 'SKIN');
            expectNoDefine(shader.fDefines, 'SKIN');
        });

        it('adds no skinning output when skin is disabled', () => {
            const shader = generate(createShader({ options: { skin: false, batch: true } }));

            expect(shader.attributes).not.toHaveProperty('vertex_boneIndices');
            expect(shader.attributes).not.toHaveProperty('vertex_boneWeights');
            expectNoDefine(shader.vDefines, 'SKIN');
            expectNoDefine(shader.vDefines, 'BATCH');
            expectNoDefine(shader.fDefines, 'SKIN');
            expectNoDefine(shader.fDefines, 'BATCH');
        });
    });

    describe('instancing', () => {

        it('adds the default instance attributes when the default instancing chunk is used', () => {
            const device = createDevice();
            ShaderChunks.get(device, SHADERLANGUAGE_GLSL).set('transformInstancingVS', 'default instancing chunk');
            const shader = generate(createShader({
                device,
                options: { useInstancing: true }
            }));

            expect(shader.attributes.instance_line1).toBe(SEMANTIC_ATTR11);
            expect(shader.attributes.instance_line2).toBe(SEMANTIC_ATTR12);
            expect(shader.attributes.instance_line3).toBe(SEMANTIC_ATTR14);
            expect(shader.attributes.instance_line4).toBe(SEMANTIC_ATTR15);
            expectDefine(shader.vDefines, 'INSTANCING', true);
            expectDefine(shader.fDefines, 'INSTANCING', true);
        });

        it('does not add instance attributes when a custom instancing chunk is used', () => {
            const device = createDevice();
            ShaderChunks.get(device, SHADERLANGUAGE_GLSL).set('transformInstancingVS', 'default instancing chunk');
            const shader = createShader({ device, options: { useInstancing: true } });
            shader.chunks.set('transformInstancingVS', 'custom instancing chunk');
            generate(shader);

            expect(shader.attributes).not.toHaveProperty('instance_line1');
            expect(shader.attributes).not.toHaveProperty('instance_line2');
            expect(shader.attributes).not.toHaveProperty('instance_line3');
            expect(shader.attributes).not.toHaveProperty('instance_line4');
            expectDefine(shader.vDefines, 'INSTANCING', true);
            expectDefine(shader.fDefines, 'INSTANCING', true);
        });

        it('adds no instancing output when instancing is disabled', () => {
            const shader = generate(createShader({ options: { useInstancing: false } }));

            expect(shader.attributes).not.toHaveProperty('instance_line1');
            expectNoDefine(shader.vDefines, 'INSTANCING');
            expectNoDefine(shader.fDefines, 'INSTANCING');
        });
    });

    describe('object level defines', () => {

        it('adds screenspace to both stages and pixelsnap only to the vertex stage', () => {
            const shader = generate(createShader({
                options: { screenSpace: true, pixelSnap: true }
            }));

            expectDefine(shader.vDefines, 'SCREENSPACE', true);
            expectDefine(shader.vDefines, 'PIXELSNAP', true);
            expectDefine(shader.fDefines, 'SCREENSPACE', true);
            expectNoDefine(shader.fDefines, 'PIXELSNAP');
        });

        it('keeps vertex-only defines out of the fragment stage', () => {
            const shader = createShader({
                options: {
                    linearDepth: true,
                    vertexColors: true,
                    useMsdf: true,
                    msdfTextAttribute: true,
                    pixelSnap: true
                }
            });
            shader.needsNormal = true;
            generate(shader);

            expect([...shader.fDefines]).toEqual([]);
        });
    });

    describe('shader language output', () => {

        it('emits GLSL varying declarations by default', () => {
            const shader = generate(createShader({ options: { linearDepth: true } }));

            expect(shader.shaderLanguage).toBe(SHADERLANGUAGE_GLSL);
            expect(shader.varyingsCode).toContain('varying vec3 vPositionW;\n');
            expect(shader.varyingsCode).toContain('varying float vLinearDepth;\n');
        });

        it('emits WGSL typed varying declarations', () => {
            const shader = generate(createShader({
                device: createDevice(true),
                allowWGSL: true,
                options: { linearDepth: true }
            }), [true, true], [true, true]);

            expect(shader.shaderLanguage).toBe(SHADERLANGUAGE_WGSL);
            expect(shader.varyingsCode).toBe([
                '#define VARYING_VPOSITIONW',
                'varying vPositionW: vec3f;',
                '#define VARYING_VLINEARDEPTH',
                'varying vLinearDepth: f32;',
                '#define VARYING_VUV0',
                'varying vUv0: vec2f;',
                '#define VARYING_VUV1',
                'varying vUv1: vec2f;',
                ''
            ].join('\n'));
        });
    });

    describe('attribute location validation', () => {

        it('reports a conflict between default instance attributes and uv set 6', () => {
            const device = createDevice();
            ShaderChunks.get(device, SHADERLANGUAGE_GLSL).set('transformInstancingVS', 'default instancing chunk');
            const shader = createShader({ device, options: { useInstancing: true } });
            const useUv = [false, false, false, false, false, false, true];

            const errors = [];
            const originalError = console.error;
            console.error = (...args) => errors.push(args);
            try {
                generate(shader, useUv);
            } finally {
                console.error = originalError;
            }

            expect(errors).toHaveLength(1);
            expect(errors[0][0]).toBe('ASSERT FAILED: ');
            expect(errors[0][1]).toContain('instance_line1');
            expect(errors[0][1]).toContain('vertex_texCoord6');
            expect(errors[0][1]).toContain('attribute location 11');
        });

        it('does not report a conflict for compatible attributes', () => {
            const shader = createShader();
            const errors = [];
            const originalError = console.error;
            console.error = (...args) => errors.push(args);
            try {
                generate(shader, [true, true], [true], [{ id: 1, uv: 0, name: 'diffuse' }]);
            } finally {
                console.error = originalError;
            }

            expect(errors).toEqual([]);
        });
    });

    describe('invalid inputs', () => {

        it('throws when useUv is not array-like', () => {
            const shader = createShader();

            expect(() => shader.generateVertexShader(null, [], [])).toThrow(TypeError);
        });

        it('throws when mapTransforms is not iterable', () => {
            const shader = createShader();

            expect(() => shader.generateVertexShader([], [], null)).toThrow(TypeError);
        });
    });
});
